This is the only thing I can find about this PSEUDOIMUL32 error: https://discussions.unity.com/t/shader-link-error-assertion-failed-false-pseudoimul32-must-not-be-seen-here/932276/8

Maybe we can do something similar:

```glsl
vec3 integrate_edge_hill(vec3 p0, vec3 p1) {
	// Approximation suggested by Hill and Heitz, calculating the integral of the spherical cosine distribution over the line between p0 and p1.
	// Runs faster than the exact formula of Baum et al. (1989).
	float cosTheta = dot(p0, p1);

	float x = cosTheta;
	float y = abs(x);
	float a = 5.42031 + (3.12829 + 0.0902326 * y) * y;
	float b = 3.45068 + (4.18814 + y) * y;
	float theta_sintheta = a / b;

	theta_sintheta = mix(
			theta_sintheta,
			M_PI * inversesqrt(1.0 - x * x) - theta_sintheta, // original paper: 0.5*inversesqrt(max(1.0 - x*x, 1e-7)) - theta_sintheta
			x < 0.0 ? 1.0 : 0.0);

	return theta_sintheta * cross(p0, p1);
}

float integrate_edge(vec3 p_proj0, vec3 p_proj1, vec3 p0, vec3 p1) {
	float epsilon = 0.00001;
	float opposite_sides = (dot(p_proj0, p_proj1) < -1.0 + epsilon) ? 1.0 : 0.0;

	// calculate the point on the line p0 to p1 that is closest to the vertex (origin)
	vec3 half_point_t = p0 + normalize(p1 - p0) * dot(p0, normalize(p0 - p1));
	vec3 half_point = normalize(half_point_t);
	float opposite_sides_result = integrate_edge_hill(p_proj0, half_point).y + integrate_edge_hill(half_point, p_proj1).y;

	return mix(integrate_edge_hill(p_proj0, p_proj1).y, opposite_sides_result, opposite_sides);
}
```

Does this work?

